"""Quiet status file; completion report is generated by the training launcher."""
from datetime import datetime
import json
from pathlib import Path
import time
from scripts.watch_search_ablation import observe, atomic_json


def main():
    root=Path('outputs/quality_il_b_20261014')
    print('OBSERVER_STARTED: quiet until completion or failure',flush=True)
    while True:
        result=observe(root,'b',session_prefix='cvtsp_quality_il')
        atomic_json(root/'running_status.json',{'observed_at':datetime.now().astimezone().isoformat(),'groups':{'b':result}})
        if result['exit_code'] not in (None,0) or (result['tmux_alive'] is False and result['exit_code']!=0):
            atomic_json(root/'observer_failure.json',result)
            print('TRAINING_FAILURE '+json.dumps(result),flush=True)
            return 1
        if result['exit_code']==0:
            log=(root/'b'/'live.log').read_text()
            report=[x for x in log.splitlines() if x.startswith('REPORT_EXIT=')]
            if report:
                code=int(report[-1].split('=')[1])
                if code:
                    print('COMPLETION_AUDIT_FAILURE',flush=True)
                    return 1
                audit=json.loads((root/'completion_audit.json').read_text())
                if not audit['passed'] or result['latest_epoch']!=20: raise RuntimeError('Incomplete B audit')
                print('QUALITY_IL_B_E20_COMPLETE',flush=True)
                return 0
            if result['tmux_alive'] is False:
                print('COMPLETION_REPORT_MISSING',flush=True)
                return 1
        time.sleep(30)


if __name__=='__main__': raise SystemExit(main())
